        tests.append(fmt([rng.randint(1, 500) for _ in range(rng.randint(1, 6))]))
    tests.append(fmt([10**18]))
    tests.append(fmt([2**59, 2**59 - 1, 2**59 + 1, 2**60 - 1 if 2**60 - 1 <= 10**18 else 10**18]))
    tests.append(fmt([rng.randint(1, 10**18) for _ in range(10000)]))
    tests.append(fmt([rng.randint(10**17, 10**18) for _ in range(10000)]))
    tests.append(fmt([10**18 - i for i in range(10000)]))
